"""
Meja Arsip - tanya jawab atas Berita Negara / Tambahan Berita Negara RI
RAG di atas hasil scraping https://beritanegara.co.id/ memakai Qwen 3.5
Satu file: logika RAG, tema cerah bertekstur, logo PNRI, dan interaksi sudah menyatu di sini.
Desain v3: tema navy kaca (glassmorphism) mengikuti mockup PNRI: rail kiri, hero foto gedung,
kartu statistik, kartu fitur, carousel lembar sumber.

Jalankan:
    pip install -r requirements.txt
    ollama pull qwen3.5
    streamlit run app2.py
"""

import hashlib
import html
import json
import math
import os
import random
import re
import time

import numpy as np
import pandas as pd
import requests
import streamlit as st
import streamlit.components.v1 as components
from sklearn.feature_extraction.text import TfidfVectorizer

# ----------------------------------------------------------------------------
# Konfigurasi dasar
