@st.cache_data(ttl=60, show_spinner=False)
def db_signature() -> str:
    """Penanda isi tabel (jumlah baris + id terakhir), jadi kunci cache data & indeks."""
    r = requests.get(sb_url(), headers={"apikey": SUPABASE_KEY, "Prefer": "count=exact"},
                     params={"select": "id", "order": "id.desc", "limit": 1}, timeout=(10, 30))
    r.raise_for_status()
    total = r.headers.get("Content-Range", "*/0").split("/")[-1]
    rows = r.json()
    return f"{total}-{rows[0]['id'] if rows else 0}"


def fetch_all() -> pd.DataFrame:
    """Ambil seluruh tabel (urut id), lalu ubah nama kolom snake_case menjadi nama tampilan (FIELDS)."""
    ses = requests.Session()
    ses.headers.update({"apikey": SUPABASE_KEY})
    out, last = [], 0
    while True:
        r = ses.get(sb_url(), params={"select": "*", "id": f"gt.{last}", "order": "id.asc", "limit": SB_PAGE},
                    timeout=(10, 60))
        r.raise_for_status()
        rows = r.json()
        if not rows:
            break
        out.extend(rows)
        last = rows[-1]["id"]
    if not out:
        return pd.DataFrame(columns=FIELDS)
    df = pd.DataFrame(out, dtype=object).drop(columns="id")
    missing = [k for k in COLUMN_MAP if k not in df.columns]
    if missing:
        raise RuntimeError("Kolom ini tidak ada di tabel Supabase: " + ", ".join(missing) +
                           ". Nama kolom harus sama persis dengan schema tabel.")
    return df.rename(columns=COLUMN_MAP)[FIELDS]


def setup_screen(kind: str, detail: str = ""):
    """Layar penyiapan satu kali. Selalu diakhiri st.stop()."""
    if kind == "no_table":
        st.markdown(f'<p class="dh">Tabel tidak ditemukan</p><p class="dp">Supabase tidak punya tabel '
                    f'<b>{SB_TABLE}</b> di schema <b>public</b> pada project <b>{esc(SB_REF)}</b>. '
                    f'Periksa nama tabel di Table Editor (harus persis <b>{SB_TABLE}</b>) dan pastikan project '
                    'yang dibuka sama dengan alamat Supabase di aplikasi ini.</p>', unsafe_allow_html=True)
    else:
        st.markdown('<p class="dh">Satu langkah penyiapan database</p>'
                    '<p class="dp">Tabel sudah berisi data. Aplikasi masih butuh kolom <b>id</b> untuk membaca data '
                    'bertahap, dan izin <b>baca-saja</b> agar data aman. Klik tombol di bawah, tempel SQL ini di '
                    'kotak yang terbuka, lalu klik <b>Run</b>. Data yang ada tidak diubah atau dihapus.</p>',
                    unsafe_allow_html=True)
        st.code(SETUP_SQL, language="sql")
        st.link_button("Buka SQL Editor Supabase", SQL_EDITOR_URL)
        st.markdown('<p class="dp" style="margin-top:12px">Setelah muncul tulisan Success, kembali ke sini dan '
                    'klik tombol berikut.</p>', unsafe_allow_html=True)
        if st.button("Saya sudah menjalankan SQL, periksa lagi", type="primary"):
            st.cache_data.clear()
            st.rerun()
    if detail:
        st.caption(f"Detail dari Supabase: {detail}")
    st.stop()


